import 'katex/dist/katex.min.css'
import http from '@/services/http'
import { enhanceMermaid } from '@/utils/mermaid'
import AppIcon from '@/components/AppIcon.vue'
import UserAvatar from '@/components/UserAvatar.vue'
type TaxonomyItem={name:string;slug:string}; type Post={id:number;title:string;username:string;blog_slug:string;avatar_url?:string|null;avatar_path?:string|null;published_at?:string|null;reading_minutes?:number;cover_image?:string|null;cover_alt_text?:string|null;excerpt?:string|null;content_html?:string|null;like_count:number;view_count?:number;bookmark_count?:number;categories?:TaxonomyItem[];tags?:TaxonomyItem[];viewer_liked?:boolean;viewer_bookmarked?:boolean;bio?:string|null;blog_title?:string|null}; type Comment={id:number;parent_id?:number|null;author_id?:number|null;username:string;content:string;created_at:string;deleted_at?:string|null}
const route=useRoute(), post=ref<Post>(), comments=ref<Comment[]>([]), related=ref<any>({ related:[], previous:null, next:null }), articleRef=ref<HTMLElement>(), loading=ref(true), commentsLoading=ref(false), error=ref(''), commentText=ref(''), replyTo=ref<number|null>(null), canComment=ref(false), actionMessage=ref(''), actionError=ref(false), commentError=ref(''), commentPending=ref(false), pendingDeleteId=ref<number|null>(null), liked=ref(false), bookmarked=ref(false), reported=ref(false), progress=ref(0), toc=ref<{id:string;level:number;text:string}[]>([])
const actionPending=ref({like:false,bookmark:false,report:false}), deleteCommentId=ref<number|null>(null), deleteConfirmButton=ref<HTMLButtonElement>(), loggedIn=localStorage.getItem('isLoggedIn')==='true', currentUserId=Number(JSON.parse(localStorage.getItem('userInfo')||'{}').id)||0
const html=computed(()=>DOMPurify.sanitize(post.value?.content_html||'',{ADD_TAGS:['audio','video','figure','figcaption','details','summary','pre','code','aside','table','thead','tbody','tr','th','td','a','img','div','span'],ADD_ATTR:['controls','src','href','download','target','rel','alt','data-callout','data-gallery','data-bookmark-card','data-embed','data-language','data-math','data-mermaid','style']}))
const requiresLogin=computed(()=>error.value.includes('登录')), loginTarget=computed(()=>({path:'/login',query:{redirect:route.fullPath}})), rootComments=computed(()=>comments.value.filter((comment)=>!comment.parent_id))
const date=(value:string|null|undefined)=>{if(!value)return'刚刚';const parsed=new Date(value);return Number.isNaN(parsed.getTime())?'刚刚':new Intl.DateTimeFormat('zh-CN',{dateStyle:'medium'}).format(parsed)}; const shareConfig=()=>route.query.share?{params:{share:String(route.query.share)}}:{}
function repliesFor(parentId:number){return comments.value.filter((comment)=>comment.parent_id===parentId)}; function setActionMessage(message:string,isError=false){actionMessage.value=message;actionError.value=isError}; function login(){window.location.assign(`/login?redirect=${encodeURIComponent(route.fullPath)}`)}
async function loadComments(){if(!post.value)return;commentsLoading.value=true;try{comments.value=(await http.get(`/api/posts/${post.value.id}/comments`,shareConfig())).data.items||[]}catch(e:any){commentError.value=e.response?.data?.error?.message||'评论暂时无法载入。'}finally{commentsLoading.value=false}}
function setMetadata(){if(!post.value)return;document.title=`${post.value.title} · Own-Web`;const description=post.value.excerpt||'';const metadata:Array<[string,string]>=[['description',description],['og:title',post.value.title],['og:description',description],['og:type','article'],['og:url',window.location.href],['og:image',post.value.cover_image||'']];for(const [property,content] of metadata){let meta=document.head.querySelector(`meta[property="${property}"],meta[name="${property}"]`) as HTMLMetaElement|null;if(!meta){meta=document.createElement('meta');meta.setAttribute(property.startsWith('og:')?'property':'name',property);document.head.appendChild(meta)}meta.content=content}}
async function enhance(){await nextTick();const root=articleRef.value;if(!root)return;const used=new Set<string>();toc.value=[...root.querySelectorAll('h1,h2,h3,h4')].map((heading,index)=>{const text=heading.textContent?.trim()||`section-${index+1}`;let id=text.toLowerCase().replace(/[^\w\u4e00-\u9fff]+/g,'-').replace(/^-|-$/g,'')||`section-${index+1}`;while(used.has(id))id+=`-${index+1}`;used.add(id);heading.id=id;return{id,level:Number(heading.tagName.slice(1)),text}});enhanceMermaid(root);root.querySelectorAll('pre code').forEach((element)=>{try{hljs.highlightElement(element as HTMLElement)}catch(_){}});root.querySelectorAll('pre').forEach((pre)=>{if(pre.querySelector('.copy-code'))return;const button=document.createElement('button');button.className='copy-code button button-secondary';button.type='button';button.textContent='复制代码';button.addEventListener('click',async()=>{await navigator.clipboard?.writeText(pre.querySelector('code')?.textContent||'');button.textContent='已复制';window.setTimeout(()=>{button.textContent='复制代码'},1400)});pre.appendChild(button)});try{renderMathInElement(root,{delimiters:[{left:'\\(',right:'\\)',display:false},{left:'$$',right:'$$',display:true}],throwOnError:false,strict:'warn',trust:false,maxSize:10,maxExpand:100})}catch(_) {}}
async function load(){loading.value=true;error.value='';commentError.value='';actionMessage.value='';try{const response=await http.get(`/api/public/posts/${route.params.slug}`,shareConfig());post.value=response.data.post;canComment.value=Boolean(response.data.canComment);liked.value=Boolean(post.value?.viewer_liked);bookmarked.value=Boolean(post.value?.viewer_bookmarked);await Promise.all([loadComments(),http.get(`/api/public/posts/${route.params.slug}/related`).then((response)=>{related.value=response.data}).catch(()=>{})]);setMetadata()}catch(e:any){error.value=e.response?.data?.error?.message||'文章不可用'}finally{loading.value=false;await enhance()}}
async function toggleLike(){if(!loggedIn)return login();if(!post.value||actionPending.value.like)return;actionPending.value.like=true;const wasLiked=liked.value,oldCount=post.value.like_count;try{if(wasLiked){await http.delete(`/api/posts/${post.value.id}/like`,shareConfig());liked.value=false;post.value.like_count=Math.max(0,oldCount-1);setActionMessage('已取消喜欢。')}else{await http.post(`/api/posts/${post.value.id}/like`,{},shareConfig());liked.value=true;post.value.like_count=oldCount+1;setActionMessage('已喜欢这篇文章。')}}catch(e:any){liked.value=wasLiked;post.value.like_count=oldCount;setActionMessage(e.response?.data?.error?.message||'操作未完成，请稍后重试。',true)}finally{actionPending.value.like=false}}
