async function shareArticle(){try{await navigator.clipboard.writeText(window.location.href);setActionMessage('文章链接已复制。')}catch(_){setActionMessage('请从浏览器地址栏复制文章链接。')}}
async function report(){if(!loggedIn)return login();if(!post.value||actionPending.value.report||reported.value)return;actionPending.value.report=true;try{await http.post('/api/reports',{postId:post.value.id,reason:'其他'},shareConfig());reported.value=true;setActionMessage('举报已提交，我们会按规则处理。')}catch(e:any){setActionMessage(e.response?.data?.error?.message||'举报未提交，请稍后重试。',true)}finally{actionPending.value.report=false}}
function startReply(comment:Comment){if(!loggedIn)return login();replyTo.value=comment.id;commentText.value='';commentError.value=''};function cancelReply(){replyTo.value=null;commentText.value=''}
async function submitComment(){if(!post.value||!commentText.value.trim()||commentPending.value)return;commentPending.value=true;try{await http.post(`/api/posts/${post.value.id}/comments`,{content:commentText.value.trim(),parentId:replyTo.value},shareConfig());commentText.value='';replyTo.value=null;await loadComments();setActionMessage('评论已发布。')}catch(e:any){commentError.value=e.response?.data?.error?.message||'评论未发布，请稍后重试。'}finally{commentPending.value=false}}
async function removeComment(id:number){deleteCommentId.value=id;await nextTick();deleteConfirmButton.value?.focus()}
function cancelDeleteComment(){deleteCommentId.value=null}
async function confirmDeleteComment(){const id=deleteCommentId.value;if(!id)return;deleteCommentId.value=null;pendingDeleteId.value=id;try{await http.delete(`/api/comments/${id}`);await loadComments();setActionMessage('评论已删除。')}catch(e:any){commentError.value=e.response?.data?.error?.message||'删除未完成，请稍后重试。'}finally{pendingDeleteId.value=null}}
function updateProgress(){const height=document.documentElement.scrollHeight-window.innerHeight;progress.value=height>0?Math.min(100,Math.max(0,(window.scrollY/height)*100)):0}
const CommentItem=defineComponent({name:'CommentItem',props:{comment:{type:Object as()=>Comment,required:true},replies:{type:Array as()=>Comment[],required:true},loggedIn:{type:Boolean,required:true},currentUserId:{type:Number,required:true},pendingDeleteId:{type:Number,default:null}},emits:['reply','remove'],setup(props,{emit}){return()=>h('div',{class:'comment-content'},[h('div',{class:'comment-meta'},[h('b',props.comment.username),h('span',{class:'muted'},` · ${date(props.comment.created_at)}`)]),h('p',props.comment.content),h('div',{class:'comment-actions'},[props.loggedIn&&!props.comment.parent_id?h('button',{class:'reply',type:'button',onClick:()=>emit('reply',props.comment)},'回复'):null,props.comment.author_id===props.currentUserId?h('button',{class:'reply delete',type:'button',disabled:props.pendingDeleteId===props.comment.id,onClick:()=>emit('remove',props.comment.id)},'删除'):null]),props.replies.length?h('div',{class:'reply-list'},props.replies.map(reply=>h('div',{class:'reply-item',key:reply.id},[h('div',{class:'comment-meta'},[h('b',reply.username),h('span',{class:'muted'},` · ${date(reply.created_at)}`)]),h('p',reply.content)]))):null])}})
watch(()=>route.fullPath,load);onMounted(()=>{load();window.addEventListener('scroll',updateProgress,{passive:true})});onBeforeUnmount(()=>window.removeEventListener('scroll',updateProgress))
</script>

<style scoped>
